import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Opciones de privacidad","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/privacy-choices.md","filePath":"es/guide/privacy-choices.md","lastUpdated":1793173149000}`),a={name:`es/guide/privacy-choices.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="opciones-de-privacidad" tabindex="-1">Opciones de privacidad <a class="header-anchor" href="#opciones-de-privacidad" aria-label="Permalink to “Opciones de privacidad”">​</a></h1><p>Sudoku es una app que funciona sin conexión en primer lugar y con prácticas mínimas en materia de datos. Esta página explica tus opciones de privacidad y cómo controlar tus datos.</p><h2 id="tus-datos-permanecen-en-tu-dispositivo-de-forma-predeterminada" tabindex="-1">Tus datos permanecen en tu dispositivo (de forma predeterminada) <a class="header-anchor" href="#tus-datos-permanecen-en-tu-dispositivo-de-forma-predeterminada" aria-label="Permalink to “Tus datos permanecen en tu dispositivo (de forma predeterminada)”">​</a></h2><ul><li>Todos los datos de juego (ajustes, estado de la partida, notas a lápiz y estadísticas) se almacenan localmente en tu dispositivo de forma predeterminada.</li><li>La jugabilidad principal no requiere ningún acceso a la red.</li><li>No hay anuncios, ni analíticas, ni rastreo.</li></ul><h2 id="funciones-en-la-nube-opcionales" tabindex="-1">Funciones en la nube opcionales <a class="header-anchor" href="#funciones-en-la-nube-opcionales" aria-label="Permalink to “Funciones en la nube opcionales”">​</a></h2><h3 id="sincronizacion-con-icloud" tabindex="-1">Sincronización con iCloud <a class="header-anchor" href="#sincronizacion-con-icloud" aria-label="Permalink to “Sincronización con iCloud”">​</a></h3><p>Si decides activar la sincronización con iCloud:</p><ul><li>Los datos se sincronizan únicamente con <strong>tu cuenta personal de iCloud</strong>, no con ningún servidor que nosotros controlemos.</li><li>CloudKit de Apple se encarga del cifrado en tránsito y en reposo.</li><li>Puedes desactivarla en cualquier momento: Ajustes → [Tu nombre] → iCloud → Apps que usan iCloud → desactiva Sudoku.</li></ul><h3 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h3><p>Si decides usar Game Center:</p><ul><li>Las puntuaciones de las clasificaciones pueden aparecer públicamente con tu nombre visible de Game Center.</li><li>El progreso de los logros lo registra Game Center.</li><li>Puedes desactivarlo cerrando la sesión de Game Center en Ajustes.</li></ul><h2 id="la-unica-funcion-de-red-que-no-es-de-nube-«mas-apps»" tabindex="-1">La única función de red que no es de nube: «Más apps» <a class="header-anchor" href="#la-unica-funcion-de-red-que-no-es-de-nube-«mas-apps»" aria-label="Permalink to “La única función de red que no es de nube: «Más apps»”">​</a></h2><p>El único otro acceso a la red es la sección opcional de <strong>«Más apps»</strong> en Ajustes, que obtiene una lista de apps hermanas. Esta función:</p><ul><li>No envía ningún dato personal: solo recupera una lista de nombres y enlaces de apps.</li><li>Puedes ignorarla por completo sin que afecte a la jugabilidad.</li><li>No te rastrea ni almacena ningún identificador.</li></ul><h2 id="borrar-tus-datos" tabindex="-1">Borrar tus datos <a class="header-anchor" href="#borrar-tus-datos" aria-label="Permalink to “Borrar tus datos”">​</a></h2><p>Para eliminar todos los datos de la app de tu dispositivo:</p><ul><li><strong>iPhone/iPad</strong>: elimina y vuelve a instalar la app</li><li><strong>Mac</strong>: cierra Sudoku y luego elimina el contenedor:</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><p>Para borrar también los datos sincronizados con iCloud:</p><ol><li>Ve a <strong>Ajustes → [Tu nombre] → iCloud → Gestionar almacenamiento de la cuenta</strong></li><li>Busca Sudoku en la lista de apps</li><li>Toca <strong>Eliminar datos</strong></li></ol><p>Esto borrará de forma permanente todos los ajustes, estadísticas, partidas guardadas y el progreso del desafío diario de iCloud.</p><h2 id="sin-rastreo-sin-anuncios" tabindex="-1">Sin rastreo, sin anuncios <a class="header-anchor" href="#sin-rastreo-sin-anuncios" aria-label="Permalink to “Sin rastreo, sin anuncios”">​</a></h2><p>Sudoku no contiene publicidad, ni analíticas, ni píxeles de rastreo, ni integraciones de intercambio de datos con terceros. La app no necesita acceso a la red para jugar.</p><h2 id="resumen-de-solicitudes-de-privacidad" tabindex="-1">Resumen de solicitudes de privacidad <a class="header-anchor" href="#resumen-de-solicitudes-de-privacidad" aria-label="Permalink to “Resumen de solicitudes de privacidad”">​</a></h2><table tabindex="0"><thead><tr><th>Solicitud</th><th>¿Obligatoria?</th><th>Qué hace</th></tr></thead><tbody><tr><td>Almacenamiento local</td><td>Sí (automático)</td><td>Guarda los datos de juego en el dispositivo</td></tr><tr><td>Sincronización con iCloud</td><td>Opcional</td><td>Sincroniza los datos entre tus dispositivos mediante CloudKit</td></tr><tr><td>Game Center</td><td>Opcional</td><td>Clasificaciones y logros</td></tr><tr><td>Red («Más apps»)</td><td>Opcional</td><td>Obtiene la lista de apps hermanas</td></tr></tbody></table><p>Como no se recopila ni se transmite ningún dato personal a servidores que nosotros controlemos, no existe una base de datos central a la que acceder, eliminar o exportar. Todos los datos son locales o están gestionados por los servicios de Apple (iCloud y Game Center).</p><h2 id="contacto" tabindex="-1">Contacto <a class="header-anchor" href="#contacto" aria-label="Permalink to “Contacto”">​</a></h2><p>Si tienes preguntas sobre este proceso, abre un issue en <code>https://github.com/sudoku-pro/sudoku-site/issues</code> o envía un correo a <a href="mailto:sudoku@w3cub.com" target="_blank" rel="noreferrer">sudoku@w3cub.com</a>.</p>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};